mapper.select:
SELECT COUNT(*) FROM inspection_work_calendar
WHERE tenant_id = #{tenantId} AND calendar_name = #{calendarName} AND deleted = 0
AND id != #{excludeId}

mapper.update:
UPDATE inspection_calendar_exception
SET deleted = 1, status = 0, updated_by = #{operatorId}, version = version + 1
WHERE tenant_id = #{tenantId} AND calendar_id = #{calendarId}
  AND id = #{id} AND deleted = 0 AND version = #{version}
